    if (!selected) return;
    setFile(selected);
    setPreview(URL.createObjectURL(selected)); // временный локальный URL картинки
  };

  useEffect(() => {
    // очистка: освобождаем память blob
    return () => { if (preview) URL.revokeObjectURL(preview); };
  }, [preview]);

  const upload = () => {
    if (!file) return;
    const xhr = new XMLHttpRequest();
    xhr.upload.onprogress = (e) => setProgress(Math.round((e.loaded / e.total) * 100));
    xhr.onload = () => console.log('Загрузка завершена');
    const formData = new FormData();
    formData.append('file', file);
